   135	    @Test
   136	    void pedidoPagamentoIdempotenteEstoqueECredito() throws Exception {
   137	        String cpf = "55555555555";
   138	        String corpo = compra(cpf, "[{\"sku\":\"MOC-001\",\"quantidade\":1}]", "RETIRADA_LOJA", null, "PIX", 1,
   139	                "PRATA", "SUDESTE", "01310100");
   140	        String resumo = chamar("/checkout/resumo", corpo).andReturn().getResponse().getContentAsString();
   141	        String a = chamar("/pedidos", corpo).andExpect(status().isCreated())
   142	                .andExpect(jsonPath("$.situacao").value("AGUARDANDO_PAGAMENTO"))
   143	                .andReturn().getResponse().getContentAsString();
   144	        String id = a.replaceAll(".*\"id\":\"([^\"]+)\".*", "$1");
   145	        assertEquals(true, a.contains(resumo));
   146	        String pagamento = "{\"idTransacao\":\"TX-1\",\"pagoEm\":\"2026-10-14T16:00:00Z\"}";
   147	        chamar("/pedidos/" + id + "/pagamento", pagamento).andExpect(status().isOk())
   148	                .andExpect(jsonPath("$.situacao").value("PAGO"));
   149	        chamar("/pedidos/" + id + "/pagamento", pagamento).andExpect(status().isOk());
   150	        mvc.perform(get("/produtos/MOC-001")).andExpect(jsonPath("$.estoque").value(0));
   151	        mvc.perform(get("/clientes/" + cpf)).andExpect(jsonPath("$.saldoCredito").value(3.20));
   152	        mvc.perform(get("/clientes/" + cpf + "/avisos")).andExpect(jsonPath("$.length()").value(1))
   153	                .andExpect(jsonPath("$[0].tipo").value("PAGAMENTO_APROVADO"))
   154	                .andExpect(jsonPath("$[0].situacao").value("NOVO"));
   155	        chamar("/pedidos/" + id + "/cancelamento", "{}").andExpect(jsonPath("$.situacao").value("CANCELADO"));
   156	        mvc.perform(get("/produtos/MOC-001")).andExpect(jsonPath("$.estoque").value(1));
   157	        mvc.perform(get("/clientes/" + cpf)).andExpect(jsonPath("$.saldoCredito").value(0.00));
   158	        chamar("/pedidos/" + id + "/envio", "{\"codigoRastreio\":\"X\"}").andExpect(status().isConflict())
   159	                .andExpect(jsonPath("$.erro").value("OPERACAO_NAO_PERMITIDA"));
   160	    }
   161	
   162	    @Test
   163	    void pagamentoExpiradoCancela() throws Exception {
   164	        String corpo = compra("77777777777", "[{\"sku\":\"MEI-001\",\"quantidade\":1}]", "RETIRADA_LOJA", null, "PIX",
   165	                1, "BRONZE", "SUDESTE", "01310100");
   166	        String a = chamar("/pedidos", corpo).andReturn().getResponse().getContentAsString();
   167	        String id = a.replaceAll(".*\"id\":\"([^\"]+)\".*", "$1");
   168	        chamar("/pedidos/" + id + "/pagamento", "{\"idTransacao\":\"TX-9\",\"pagoEm\":\"2099-01-01T00:00:00Z\"}")
   169	                .andExpect(status().isConflict()).andExpect(jsonPath("$.erro").value("PEDIDO_EXPIRADO"));
   170	        mvc.perform(get("/pedidos/" + id)).andExpect(jsonPath("$.situacao").value("CANCELADO"));
   171	        mvc.perform(get("/pedidos/inexistente")).andExpect(status().isNotFound());
   172	    }
