   185	    void vetorDaRfc7677() throws Exception {
   186	        Class<?> tipo = Class.forName("com.loja.persistencia.Scram");
   187	        var construtor = tipo.getDeclaredConstructor(String.class, String.class, String.class);
   188	        construtor.setAccessible(true);
   189	        Object scram = construtor.newInstance("user", "pencil", "rOprNGfwEbeRWgbNEkqO");
   190	        var metodo = tipo.getDeclaredMethod("mensagemFinal", String.class);
   191	        metodo.setAccessible(true);
   192	        String resposta = (String) metodo.invoke(scram,
   193	                "r=rOprNGfwEbeRWgbNEkqO%hvYDpWUa2RaTCAfuxFIlj)hNlF$k0,s=W22ZaJ0SNY7soEsUEjb6gQ==,i=4096");
   194	        assertEquals("c=biws,r=rOprNGfwEbeRWgbNEkqO%hvYDpWUa2RaTCAfuxFIlj)hNlF$k0,"
   195	                + "p=dHzbZapWIk4jUhN+Ute9ytag9zjfMHgsqmmiz7AndVQ=", resposta);
   196	    }
